import time
import random
import datetime

class BotGame:
    def __init__(self):
        self.money = 5000
        self.salary = 2000
        self.tax_rate = 0.1
        self.rent = 3000
        self.time = datetime.datetime(2025, 3, 22, 8, 0)
        self.relationship = 0
        self.is_working = False
        self.galya_debt = 0
        self.city = "Mukhosransk"

    def show_status(self):
        print(f"\n📍 {self.city} | 💰 {self.money} RUB | 🕒 {self.time.strftime('%H:%M')} | ❤️ {self.relationship}/100 | 🏠 Rent: {self.galya_debt} RUB")

    def work_shift(self):
        if self.is_working:
            return print("You're already working!")
        self.is_working = True
        time.sleep(1)
        self.money += self.salary
        self.time += datetime.timedelta(hours=8)
        print(f"+{self.salary} RUB | Shift ended")
        self.is_working = False

    def pay_taxes(self):
        tax = int(self.money * self.tax_rate)
        if self.money >= tax:
            self.money -= tax
            print(f"Taxes paid: {tax} RUB")
        else:
            print("Not enough money!")

    def pay_rent(self):
        if self.money >= self.rent:
            self.money -= self.rent
            self.galya_debt = 0
            print("Rent paid. Galya grumbles but takes it.")
        else:
            self.galya_debt += self.rent
            print("Galya: 'No money again?! One more missed payment and you're out!'")

    def talk_to_galya(self):
        print("\nGalya: 'Where’s my money?!'")
        self.pay_rent()

    def talk_to_bot(self):
        print("\nLisa looks at you.")
        if self.relationship < 30:
            print("Lisa: 'Working too much?'")
            self.relationship += 5
        elif self.money >= 500:
            self.money -= 500
            self.relationship += 15
            print("Lisa smiles. (+15 ❤️)")
        else:
            print("Lisa: 'Hmm...' (+5 ❤️)")

    def advance_time(self, hours):
        self.time += datetime.timedelta(hours=hours)
        print(f"+{hours}h passed.")

    def random_event(self):
        events = [
            lambda: print("\n📺 Reporters want an interview! (+1000 RUB)" if random.randint(0, 1) else "\n📺 You refused."),
            lambda: print(f"\n💰 Found {random.randint(500, 3000)} RUB!"),
            lambda: print("\n🚨 You fought off a thief!" if random.randint(0, 2) else f"\n🚨 Robbed! Lost {random.randint(500, 2000)} RUB.")
        ]
        random.choice(events)()

    def start(self):
        while True:
            self.show_status()
            action = input("\n1-Work | 2-Taxes | 3-Lisa | 4-Galya | 5-Skip 2h | 6-Event | 7-Exit\n> ")

            if action == "1": self.work_shift()
            elif action == "2": self.pay_taxes()
            elif action == "3": self.talk_to_bot()
            elif action == "4": self.talk_to_galya()
            elif action == "5": self.advance_time(2)
            elif action == "6": self.random_event()
            elif action == "7": break
            else: print("Invalid input!")

game = BotGame()
game.start()
